pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;
    function setUp() public { c = new AirDropContract(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs) public {
        vm.assume(contract_address != address(0x0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        RogueToken rogue = new RogueToken(true);
        bool ok;
        try c.transfer(address(rogue), tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}

contract RogueToken {
    bool public shouldRevert;
    constructor(bool _shouldRevert) { shouldRevert = _shouldRevert; }
    function transferFrom(address, address, uint256) external returns (bool) {
        require(!shouldRevert, "forced revert");
        return true;
    }
}
